INSERT [dbo].[ChatMessages] ([Id], [ConversationId], [Role], [Content], [SourcesJson], [TokenCount], [Feedback], [CreatedAt]) VALUES (N'284691d5-8567-4d66-8942-4678230bc53b', N'ec94e4ef-9375-423c-b492-2e4352802596', N'assistant', N'According to the document, each entry in the book contains material from Wikipedia, and the URL at the bottom of each page will direct you to the source Wikipedia article. Additionally, the book''s copyright information states that "This book is dedicated to every person who wrote an entry that appears in it." (Source: page 5 of the 50 page sample PDF.indd.pdf)', N'["50 page sample PDF.indd.pdf (page 6)","50 page sample PDF.indd.pdf (page 18)","50 page sample PDF.indd.pdf (page 23)","50 page sample PDF.indd.pdf (page 4)","50 page sample PDF.indd.pdf (page 5)"]', 61, N'down', CAST(N'2026-04-01T15:25:14.0874947' AS DateTime2))
GO
INSERT [dbo].[ChatMessages] ([Id], [ConversationId], [Role], [Content], [SourcesJson], [TokenCount], [Feedback], [CreatedAt]) VALUES (N'3b8a432f-c6cb-4576-b854-5d07d1f1ea48', N'ec94e4ef-9375-423c-b492-2e4352802596', N'assistant', N'The document appears to be a sample PDF book with 50 pages. The content of the book includes a disclaimer and copyright information regarding the use of material from Wikipedia. Specifically, it states that the book contains material from Wikipedia, but may not represent the current version of any article, and provides information about the Creative Commons-Attribution Share Alike 3.0 license under which the material can be used. (Source: page 4 of the 50 page sample PDF.indd.pdf)', N'["50 page sample PDF.indd.pdf (page 5)","50 page sample PDF.indd.pdf (page 4)"]', 77, N'up', CAST(N'2026-04-01T15:24:48.6635543' AS DateTime2))
GO
INSERT [dbo].[ChatMessages] ([Id], [ConversationId], [Role], [Content], [SourcesJson], [TokenCount], [Feedback], [CreatedAt]) VALUES (N'5438c189-830c-40b7-a9d4-7a99ebaddd2a', N'f359523b-340c-42d7-8e13-759acec17879', N'assistant', N'According to document [Source: 50 page sample PDF.indd.pdf (page 5)], "This book is dedicated to every person who wrote an entry that appears in it. May your citations always be needed."

Additionally, on page 4 of the same document, it states: "All material in this book that is taken from Wikipedia is licensed under the Creative Commons-Attribution Share Alike 3.0 license." However, it does not specifically mention who contributed to the content.

However, according to page 6 of the same document, it mentions that "The Encyclopedia That Anyone Can Edit will probably be the first place you check." This implies that anyone can edit Wikipedia articles, but it does not provide information on who specifically contributed to the content of this book.', N'["50 page sample PDF.indd.pdf (page 6)","50 page sample PDF.indd.pdf (page 23)","50 page sample PDF.indd.pdf (page 4)","50 page sample PDF.indd.pdf (page 5)","50 page sample PDF.indd.pdf (page 18)"]', 120, N'up', CAST(N'2026-04-05T08:18:07.9148773' AS DateTime2))
GO
