INSERT [dbo].[HelpFaqs] ([Id], [CategoryId], [Question], [Answer], [SortOrder], [IsActive], [ViewCount], [CreatedAt], [UpdatedAt]) VALUES (N'5dff2451-fe49-49b9-8384-173aa8b88e18', N'415d3d70-d7c4-4b83-a8a1-3617ed6aec8c', N'How do I export a report?', N'Open the Reports section, select your report, and click the Export button in the top-right. Available formats: PDF, Excel, CSV.', 1, 1, 0, CAST(N'2026-04-04T16:35:35.5526003' AS DateTime2), CAST(N'2026-04-04T16:35:35.5526004' AS DateTime2))
