INSERT [dbo].[HelpFaqs] ([Id], [CategoryId], [Question], [Answer], [SortOrder], [IsActive], [ViewCount], [CreatedAt], [UpdatedAt]) VALUES (N'6da3f8ae-9d49-4a3f-8089-32bd53c3d792', N'c2db68c1-1d60-4246-85c7-a95a9600fb74', N'How do I get started with the portal?', N'Log in with your corporate credentials. Your administrator will have assigned you a role — Employee, Manager, or Admin. Navigate using the left sidebar. The Dashboard gives you an overview of your workspace.', 1, 1, 0, CAST(N'2026-04-04T16:35:35.5521382' AS DateTime2), CAST(N'2026-04-04T16:35:35.5522184' AS DateTime2))
GO
INSERT [dbo].[HelpFaqs] ([Id], [CategoryId], [Question], [Answer], [SortOrder], [IsActive], [ViewCount], [CreatedAt], [UpdatedAt]) VALUES (N'c8fe5d59-6f13-430e-a119-3bd23f960d71', N'415d3d70-d7c4-4b83-a8a1-3617ed6aec8c', N'How often are reports refreshed?', N'Reports refresh automatically every 30 minutes. You can force a refresh by clicking the refresh icon on any report card.', 2, 1, 0, CAST(N'2026-04-04T16:35:35.5526005' AS DateTime2), CAST(N'2026-04-04T16:35:35.5526006' AS DateTime2))
GO
INSERT [dbo].[HelpFaqs] ([Id], [CategoryId], [Question], [Answer], [SortOrder], [IsActive], [ViewCount], [CreatedAt], [UpdatedAt]) VALUES (N'cdad1bd2-200c-4133-a7bc-4fb93193f728', N'af7e1a69-9ff8-4a4e-a20b-f23028dbdbfb', N'Can I share files with other users?', N'File sharing is managed by your administrator through role-based permissions. Contact your admin to request access to shared file folders.', 2, 1, 0, CAST(N'2026-04-04T16:35:35.5525999' AS DateTime2), CAST(N'2026-04-04T16:35:35.5525999' AS DateTime2))
