INSERT [dbo].[HelpFaqs] ([Id], [CategoryId], [Question], [Answer], [SortOrder], [IsActive], [ViewCount], [CreatedAt], [UpdatedAt]) VALUES (N'1592a330-fab7-4f45-a503-657d21c43035', N'84cc1587-32ff-49c6-8ad3-db3f555afce1', N'How does the AI Chat work?', N'The Chat uses Retrieval-Augmented Generation (RAG) — it searches your uploaded documents to answer questions. Upload files in the Files section first, then ask questions about them in Chat.', 1, 1, 0, CAST(N'2026-04-04T16:35:35.5525976' AS DateTime2), CAST(N'2026-04-04T16:35:35.5525977' AS DateTime2))
GO
