INSERT [dbo].[HelpFaqs] ([Id], [CategoryId], [Question], [Answer], [SortOrder], [IsActive], [ViewCount], [CreatedAt], [UpdatedAt]) VALUES (N'c3cf639d-c399-4a26-84f6-9e0516ffa53a', N'af7e1a69-9ff8-4a4e-a20b-f23028dbdbfb', N'What file types can I upload?', N'Supported: PDF, DOCX, XLSX, TXT, CSV, PNG, JPG. Max file size is 50MB. Files are automatically indexed for AI search after upload.', 1, 1, 0, CAST(N'2026-04-04T16:35:35.5525981' AS DateTime2), CAST(N'2026-04-04T16:35:35.5525982' AS DateTime2))
